def pipeline_pv(peak,margin,prob,launch,rate):
 ramp=[.1,.25,.5,.75,1,1,1,1,1,.8,.5,.2]
 return sum(peak*margin*prob*z/(1+rate)**(launch-2026+i) for i,z in enumerate(ramp))
